-- Bootstrap the operator company and operator technical contact user into the DB
DECLARE
  v_business_entity_key business_entity.business_entity_key%TYPE;
  v_user_cnt NUMBER := 0;
BEGIN
  -- get the operator company
  BEGIN
    SELECT business_entity_key INTO v_business_entity_key
    FROM business_entity
    WHERE business_entity_identifier = '@e2.ssp.co.company.id@'
    AND business_entity_type_key = 0;
    
    EXCEPTION
	  WHEN NO_DATA_FOUND THEN NULL;
  END;
  
  -- if the operator company does not exist create it
  IF v_business_entity_key IS NULL THEN
    SELECT business_entity_seq.nextval
    INTO v_business_entity_key
    FROM DUAL;
    
    BUSINESS_ENTITY_EXTERNAL_ID, BUSINESS_ENTITY_TYPE_KEY, DATA_SOURCE, INSERT_DT, UPDATE_DT,
    DELETE_FLAG, CURRENT_FLAG)
    VALUES (v_business_entity_key, '@e2.ssp.co.company.id@', '@e2.ssp.co.company.name@',
    sys_guid(), 0, 'MCM', systimestamp, systimestamp,
    'N', 'Y');
  END IF;
  
  -- check to see if the operator user exists
  BEGIN
    SELECT count(*) INTO
    v_user_cnt
    FROM pcm_user
    WHERE user_id = '@e2.bootstrap.user.0.userid@'
    AND business_entity_key = v_business_entity_key;
    
    EXCEPTION
	  WHEN NO_DATA_FOUND THEN NULL;
  END;

  -- if the operator user does not exist create it
  IF v_user_cnt = 0 THEN
    VALUES (pcm_user_seq.nextval, '@e2.bootstrap.user.0.userid@',
    '@e2.bootstrap.user.0.first.name@'||' '||'@e2.bootstrap.user.0.last.name@', v_business_entity_key, NULL, 1, 'Y');
  END IF;
END;
/












