DELETE FROM PCM_ROLE_RESPONSIBILITY;
declare
	v_admin pcm_role.role_key%TYPE;
	v_bus_admin pcm_role.role_key%TYPE;
begin
	select role_key into v_admin from pcm_role where role_id = 'ADMIN';
	select role_key into v_bus_admin from pcm_role where role_id = 'BUS_ADMIN';
	
	-- Administrator Role
	SELECT v_admin,RESPONSIBILITY_KEY
	FROM PCM_RESPONSIBILITY
	WHERE RESPONSIBILITY_KEY != 'VIEWER'
	AND RESPONSIBILITY_KEY != 'BUYER';
	
	-- Business Administrator Role
	SELECT v_bus_admin,RESPONSIBILITY_KEY
	FROM PCM_RESPONSIBILITY
	WHERE RESPONSIBILITY_KEY != 'VIEWER'
	AND RESPONSIBILITY_KEY != 'BUYER';
	
	-- All Roles
	SELECT ROLE_KEY,'VIEWER'
	FROM PCM_ROLE;
end;
